/****************************************************************************
 * board/beken/chips/bk7258/bk7258_camera_imgdata.c
 *
 * BK7258 GC2145 camera platform (imgdata) driver: NuttX V4L2
 * imgdata_ops_s implementation for the YUV_BUF whole-frame direct-capture
 * path.  This is the platform data interface half of the driver split
 * described in the openvela Camera Driver Framework guide; sensor-specific
 * I2C register programming lives in the imgsensor half
 * (board/beken/boards/bk7258/bk7258-ap/src/bk7258_camera_imgsensor.c).
 *
 * Capture model
 * -------------
 * YUV_BUF writes a complete YUV422 frame straight into the V4L2 frame
 * buffer (which imgdata_ops_s.alloc() takes from PSRAM) and raises the
 * YUV_ARV interrupt when the frame is done.  That is the reference
 * implementation's pure-YUV path: bk_avdk_smp
 * ap/components/bk_dvp/src/bk_dvp.c dvp_camera_yuv_mode() points
 * em_base_addr at the frame buffer, and dvp_camera_yuv_eof_handler()
 * (registered on YUV_BUF_YUV_ARV) hands the finished frame up and
 * re-points em_base_addr at the next one.  There is no line-batch
 * ping-pong buffer and no DMA copy in this path -- the previous revision
 * of this driver reconstructed frames from ~60 SM0_WR/SM1_WR line-done
 * interrupts per frame plus one DMA transfer each, which is what the
 * reference only does for the combined YUV+encode formats.
 *
 * Interrupt-context rules
 * -----------------------
 * v4l2_cap.c's complete_capture() runs in interrupt context and, from
 * there, calls back into IMGDATA_SET_BUF() (to re-arm the next buffer)
 * and IMGDATA_STOP_CAPTURE()/IMGSENSOR_STOP_CAPTURE() (when it runs out
 * of vacant containers).  So set_buf() and stop_capture(), not just the
 * frame callback, must be interrupt-safe: no printf(), no blocking, no
 * allocation.  Diagnostics in those functions are guarded by
 * up_interrupt_context().
 *
 * Capture watchdog
 * ----------------
 * VIDIOC_DQBUF blocks in nxsem_wait_uninterruptible() with no timeout
 * (v4l2_cap.c capture_dqbuf()), so if the hardware never completes a
 * frame the caller's dequeue thread never returns -- which is exactly how
 * `nxcamera stream` ended up unable to process its own `q` command
 * (nxcamera_stop() posts VIDEO_MSG_STOP and then blocks in pthread_join()
 * on that thread).  This driver therefore runs a watchdog while capturing
 * and reports an error frame if no YUV_ARV arrives within
 * BK7258_CAMERA_WATCHDOG_MS: complete_capture() completes the buffer with
 * V4L2_BUF_FLAG_ERROR and posts dqbuf_wait_flg, so DQBUF returns, the
 * application loop regains control and a stop request can be honoured.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/clock.h>
#include <nuttx/irq.h>
#include <nuttx/spinlock.h>
#include <nuttx/wdog.h>

#include <sys/time.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <errno.h>

#include <nuttx/video/imgdata.h>

#include "bk7258_yuv_buf.h"
#include "bk7258_jpeg_enc.h"
#include "bk7258_dma.h"
#include "bk7258_camera_imgdata.h"
/****************************************************************************
 * board/beken/chips/bk7258/bk7258_yuv_buf.c
 *
 * BK7258 YUV_BUF controller, YUV direct-capture mode only.  Register
 * layout source: bk_avdk_smp release/v3.1.1
 * ap/middleware/soc/bk7258_ap/soc/yuv_buf_struct.h and
 * ap/middleware/soc/bk7258_ap/hal/yuv_buf_ll.h.
 *
 * Register map (byte offset from BK7258_YUV_BUF_BASE):
 *   dev_id        0x00 - read-only module identity
 *   dev_version   0x04 - read-only module version
 *   global_ctrl   0x08 - bit[0] soft_reset, bit[1] clk_gate_bypass
 *   dev_status    0x0c - read-only module status
 *   ctrl          0x10 - bit[0] yuv_mode, bit[2:3] yuv_fmt_sel,
 *                         bit[6] hsync_rev, bit[7] vsync_rev,
 *                         bit[9] sync_edge_dect_en, bit[10:11] mclk_div,
 *                         bit[12] h264_mode, bit[13] bps_cis,
 *                         bit[14] memrev, bit[19] soi_hsync
 *   pixel         0x14 - bit[0:7] x_pixel, bit[8:15] y_pixel,
 *                         bit[16:31] frame_blk
 *   em_base_addr  0x20 - frame writer destination
 *   int_en        0x24 - bit[0] vsync_nege, bit[1] yuv_arv,
 *                         bit[2] sm0_wr, bit[3] sm1_wr, bit[4] sen_full,
 *                         bit[5] enc_line, bit[6] sen_resl,
 *                         bit[7] h264_err, bit[8] enc_slow
 *   int_status    0x28 - same bit order as int_en (write-1-to-clear)
 *   int_masks     0x2c - bit[0:1] vsync_nege, bit[2] resl_err,
 *                         bit[3] sens_full, bit[4] enc_slow,
 *                         bit[5] h264_err
 *   emr_base_addr 0x30 - resize-path destination (same value as
 *                         em_base_addr for whole-frame capture)
 *   resize_pixel  0x34 - bit[1:8] x_pixel, bit[9:16] y_pixel
 *
 * x_pixel/y_pixel are width/height divided by 8 (matching bk_dvp.c's
 * "yuv_mode_config.x_pixel = config->width / 8"); frame_blk = x_pixel *
 * y_pixel / 2.
 *
 * Power/clock: enabling this module requires clearing the video
 * pipeline's shared power-down bit and setting its own clock gate, both
 * in the system controller's register space
 * (ap/middleware/driver/yuv_buf/yuv_buf_driver.c yuv_buf_init_common())
 * -- neither is part of YUV_BUF's own register block.  bk_avdk_smp
 * enables the H264 clock gate alongside YUV_BUF's even for pure YUV
 * direct-capture mode; both are set here to match.
 *
 * Capture model: whole-frame direct write into PSRAM.  em_base_addr /
 * emr_base_addr point at the caller's frame buffer and the hardware
 * raises YUV_ARV (int bit[1]) once a complete frame has been written --
 * exactly what the reference does for pure IMAGE_YUV
 * (dvp_camera_yuv_mode() + dvp_camera_yuv_eof_handler()).  The
 * SM0_WR/SM1_WR line-batch interrupts are not used here; see
 * include/bk7258_yuv_buf.h for why.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/irq.h>
#include <nuttx/spinlock.h>
/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_camera_imgsensor.c
 *
 * GC2145 sensor-side (imgsensor) driver: NuttX V4L2 imgsensor_ops_s
 * implementation.  This is the sensor device layer half of the driver
 * split described in the openvela Camera Driver Framework guide -- it
 * owns I2C register programming, power/reset sequencing, and DVP
 * pinmux/MCLK setup; the platform (YUV_BUF/DMA/full-frame-assembly)
 * half lives in board/beken/chips/bk7258/bk7258_camera_imgdata.c.
 *
 * Register tables (g_gc2145_init_regs, g_gc2145_640_480_regs) and the
 * power/reset/pinmux/MCLK sequence below are ported from bk_avdk_smp
 * release/v3.1.1 ap/components/bk_peripheral/src/dvp/dvp_gc2145.c and
 * ap/components/bk_dvp/src/dvp_common.c, cross-checked against
 * AIDK_AI玩具开发板_原理图.pdf for this board's actual pin assignment
 * (GC2145's I2C bus is bit-banged on GPIO42/43, not the SoC's hardware
 * I2C1 peripheral -- see bk7258_gc2145_i2c_bitbang.h).
 *
 * MCLK note: GPIO27 requires pinmux function index 1
 * (GPIO_DEV_CLK_AUXS_CIS), not the index-0 function the other DVP pins
 * use, plus the system controller's AUXS_CIS clock-source-select +
 * divider + gate-enable sequence -- pinmux selection alone does not
 * drive a clock signal onto the pin.  GC2145's power-up sequence
 * requires MCLK to be applied before its I2C/SCCB interface responds.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>

#include <stddef.h>
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <errno.h>

#include <nuttx/video/imgsensor.h>
#include <sys/videoio.h>

#include "arm_internal.h"
#include "bk7258_gpio.h"
#include "bk7258_gc2145_i2c_bitbang.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define GC2145_I2C_ADDR       0x3Cu

#define DVP_MCLK_PIN          27u
#define DVP_MCLK_PINMUX_FUNCTION 1u  /* GPIO_DEV_CLK_AUXS_CIS */

#define DVP_PCLK_PIN          29u
#define DVP_HSYNC_PIN         30u
#define DVP_VSYNC_PIN         31u
#define DVP_DATA_PIN(i)       (32u + (i))
#define DVP_PINMUX_FUNCTION   0u    /* GPIO_DEV_JPEG_{PCLK,HSYNC,VSYNC,PXDATAn} */

#define DVP_RESET_PIN         28u
/****************************************************************************
 * board/beken/boards/bk7258/bk7258-ap/src/bk7258_gc9d01_fb.c
 *
 * openvela framebuffer driver for the GC9D01 panels (160x160 round, RGB565,
 * one per QSPI controller).  Implements the three hooks fb_register() needs
 * -- up_fbinitialize(), up_fbgetvplane(), up_fbuninitialize() -- plus the
 * fb_vtable_s entries required for a panel that has no autonomous refresh:
 * getvideoinfo, getplaneinfo and updatearea.
 *
 * Why updatearea is mandatory here: a RAM-less RGB parallel panel is
 * scanned out continuously by an LCD controller, so writing the
 * framebuffer is enough.  GC9D01 has its own GRAM and is written over a
 * serial bus, so nothing reaches the glass until the driver explicitly
 * pushes it.  Without CONFIG_FB_UPDATE + this callback the screen would
 * simply never change.
 *
 * ---------------------------------------------------------------------
 * Multiple displays
 * ---------------------------------------------------------------------
 * fb_register(display, plane) (include/nuttx/video/fb.h) calls
 * up_fbinitialize(display), then up_fbgetvplane(display, plane), then
 * fb_register_device(), which names the node /dev/fb<display>.  So exposing
 * two panels is just a matter of calling fb_register() twice.
 *
 * The constraint that shapes this file: fb_vtable_s's callbacks receive
 * only the vtable pointer, with no display argument.  A single shared
 * vtable therefore cannot tell which panel it is being asked about.  Each
 * display consequently gets its own state structure whose *first* member is
 * the vtable, so a callback can recover its own state by casting the vtable
 * pointer back (the usual container-of trick, valid here because the vtable
 * sits at offset 0).
 *
 * Framebuffers come from the kernel heap: 2 x 51200 = 100KB out of roughly
 * 300KB, which is affordable and much faster for the CPU to write than
 * PSRAM (which is mapped non-cacheable).  The camera's own frame buffers do
 * live in PSRAM -- they are 614400 bytes each and have no alternative.
 *
 * The panels are round: the corners of the 160x160 square are not visible.
 * That is a composition concern for whatever draws into the framebuffer,
 * not something this driver compensates for.
 *
 * SPDX-License-Identifier: Apache-2.0
 ****************************************************************************/

#include <nuttx/config.h>
#include <nuttx/arch.h>
#include <nuttx/kmalloc.h>
#include <nuttx/clock.h>
#include <nuttx/video/fb.h>

