#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate the machine-maintained half of codemap/ (an Obsidian vault).

The hand-written pages under codemap/architecture/ explain *why* and *how*
things fit together.  This script generates codemap/generated/, which is the
*inventory*: one page per source file (leading comment, exported functions,
local includes, Kconfig references, device nodes), plus cross-cutting index
pages (Kconfig options, device nodes, NSH commands, symbol index).

Design rules:

  * Output is deterministic.  No timestamps, no absolute paths, everything
    sorted.  That is what makes `--check` able to detect staleness by
    comparing a single digest instead of diffing a whole tree.
  * File discovery goes through git (tracked + untracked-not-ignored), so
    anything .gitignore excludes (docs/, notes/, sim_tests/, *.a ...) never
    leaks into a committed map, and newly added files show up automatically.
  * Nothing outside codemap/ is written.  This script never modifies source.

Usage:
    python3 codemap/_tools/gen_codemap.py            # regenerate
    python3 codemap/_tools/gen_codemap.py --check     # is the map stale?
"""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import shutil
import subprocess
import sys
from collections import defaultdict
from pathlib import Path

TOOL_VERSION = "1.0.0"

TOOLS_DIR = Path(__file__).resolve().parent
VAULT_DIR = TOOLS_DIR.parent                 # codemap/
REPO_DIR = VAULT_DIR.parent                  # repository root
GEN_DIR = VAULT_DIR / "generated"
FILES_DIR = GEN_DIR / "files"
ARCH_DIR = VAULT_DIR / "architecture"
STAMP = GEN_DIR / "_stamp.json"

SCAN_DIRS = ("board", "app", "quickapp", "external")

CODE_EXT = {".c", ".h", ".cpp", ".cc", ".hpp"}
TEXT_EXT = CODE_EXT | {
    ".py", ".sh", ".md", ".csv", ".json", ".patch", ".ld", ".script", ".xml",
    ".txt", ".defs", ".mk", ".cmake", ".yml", ".yaml", ".css", ".js", ".ux",
}
SPECIAL_NAMES = {
    "Kconfig", "Make.defs", "Makefile", "CMakeLists.txt", "defconfig",
    "ld.script", "manifest.json",
}

GENERATED_BANNER = (
    "> [!info] 自动生成\n"
    "> 本页由 `codemap/_tools/gen_codemap.py` 从源码提取，**请勿手工编辑**。\n"
    "> 需要补充判断/背景的内容请写到 `codemap/architecture/` 下的手写页，"
    "并从那里链接过来（生成器会自动回填反向链接）。\n"
)

C_KEYWORDS = {
    "if", "for", "while", "switch", "return", "else", "do", "sizeof",
    "typedef", "struct", "union", "enum", "case", "defined", "static_assert",
    "extern", "goto", "break", "continue", "default", "asm", "__asm__",
    "DEBUGASSERT", "ASSERT", "PANIC",
}


# --------------------------------------------------------------------------
# helpers
# --------------------------------------------------------------------------
def git(*args: str) -> str:
    return subprocess.run(
        ["git", "-C", str(REPO_DIR), *args],
        check=True, capture_output=True, text=True,
    ).stdout


def discover() -> list[str]:
    """Tracked + untracked-but-not-ignored files under SCAN_DIRS."""
    out: set[str] = set()
    for listing in (
        git("ls-files", "--", *SCAN_DIRS),
        git("ls-files", "--others", "--exclude-standard", "--", *SCAN_DIRS),
    ):
        for line in listing.splitlines():
            line = line.strip()
            if not line:
                continue
            p = REPO_DIR / line
            if not p.is_file():
                continue
            if p.name in SPECIAL_NAMES or p.suffix in TEXT_EXT:
                out.add(line)
    return sorted(out)


def layer_of(rel: str) -> str:
    if rel.startswith("board/beken/chips/"):
        return "chip"
    if rel.startswith("board/beken/boards/"):
        return "board"
    if rel.startswith("board/contest_board/"):
        return "board-sample"
    if rel.startswith("app/"):
        return "app"
    if rel.startswith("quickapp/"):
        return "quickapp"
    if rel.startswith("external/"):
        return "cp-vendor"
    return "other"


LAYER_TITLE = {
    "chip": "芯片层 (board/beken/chips/bk7258)",
    "board": "板级层 (board/beken/boards/bk7258/bk7258-ap)",
    "board-sample": "赛事示例板 (board/contest_board)",
    "app": "应用层 (app/)",
    "quickapp": "快应用 (quickapp/)",
    "cp-vendor": "CP 侧厂商覆盖文件 (external/bk_avdk_smp)",
    "other": "其他",
}


def kind_of(rel: str) -> str:
    name = os.path.basename(rel)
    ext = os.path.splitext(rel)[1]
    if name == "Kconfig":
        return "kconfig"
    if name == "defconfig":
        return "defconfig"
    if name == "CMakeLists.txt" or ext == ".cmake":
        return "cmake"
    if name in ("Makefile", "Make.defs") or ext in (".mk", ".defs"):
        return "make"
    if name == "ld.script" or ext in (".ld", ".script"):
        return "linker"
    if ext in (".c", ".cpp", ".cc"):
        return "c-source"
    if ext in (".h", ".hpp"):
        return "c-header"
    if ext == ".sh":
        return "shell"
    if ext == ".py":
        return "python"
    if ext == ".md":
        return "doc"
    if ext == ".patch":
        return "patch"
    return ext.lstrip(".") or "file"


def read(rel: str) -> str:
    return (REPO_DIR / rel).read_text(encoding="utf-8", errors="replace")


def page_path(rel: str) -> str:
    """Vault-relative path (no .md) of the generated page for a source file."""
    return f"generated/files/{rel}"


def link(rel: str, label: str | None = None) -> str:
    return f"[[{page_path(rel)}|{label or os.path.basename(rel)}]]"


# --------------------------------------------------------------------------
# extraction
# --------------------------------------------------------------------------
def leading_comment(text: str) -> str:
    """Consecutive comment blocks at the top of a C file, de-starred."""
    blocks: list[str] = []
    i = 0
    n = len(text)
    while len(blocks) < 3:
        while i < n and text[i] in " \t\r\n":
            i += 1
        if text.startswith("/*", i):
            end = text.find("*/", i)
            if end < 0:
                break
            blocks.append(text[i + 2:end])
            i = end + 2
            continue
        if text.startswith("//", i):
            end = text.find("\n", i)
            if end < 0:
                end = n
            blocks.append(text[i + 2:end])
            i = end
            continue
        break

    lines: list[str] = []
    for block in blocks:
        for raw in block.splitlines():
            s = raw.strip()
            if set(s) <= {"*", "/", " "}:
                s = ""
            else:
                s = re.sub(r"^\*+\s?", "", s)
            lines.append(s.rstrip())

    while lines and not lines[0]:
        lines.pop(0)
    while lines and not lines[-1]:
        lines.pop()

    out: list[str] = []
    blank = False
    for s in lines:
        if not s:
            blank = True
            continue
        if blank and out:
            out.append("")
        blank = False
        out.append(s)

    body = "\n".join(out)
    body = re.sub(r"\n?SPDX-License-Identifier:[^\n]*\n?", "\n", body).strip()
    limit = 2600
    if len(body) > limit:
        cut = body.rfind("\n\n", 0, limit)
        body = body[: cut if cut > 400 else limit].rstrip()
        body += "\n\n*（此处截断，完整说明见源文件文件头）*"
    return body


def shell_or_python_header(text: str) -> str:
    out: list[str] = []
    for raw in text.splitlines()[:40]:
        s = raw.strip()
        if s.startswith("#!"):
            continue
        if s.startswith("#"):
            s = s.lstrip("#").strip()
            if set(s) <= {"=", "-", "#", " "}:
                s = ""
            out.append(s)
            continue
        if s.startswith(('"""', "'''")):
            continue
        if not s and out:
            break
        if not s:
            continue
        break
    while out and not out[0]:
        out.pop(0)
    while out and not out[-1]:
        out.pop()
    return "\n".join(out).strip()


def c_functions(text: str) -> list[tuple[int, str, str]]:
    """[(line, name, signature)] for top-level function *definitions*."""
    lines = text.splitlines()
    res: list[tuple[int, str, str]] = []
    i = 0
    while i < len(lines):
        ln = lines[i]
        if (
            not ln
            or ln[0].isspace()
            or ln[0] in "#*/}{)]&|,;\"'"
            or "(" not in ln
        ):
            i += 1
            continue

        buf = ""
        j = i
        while j < len(lines) and j < i + 12:
            buf = (buf + " " + lines[j].strip()).strip()
            if buf.count("(") and buf.count("(") <= buf.count(")"):
                break
            j += 1
        else:
            i += 1
            continue
        if buf.count("(") > buf.count(")"):
            i += 1
            continue

        head = buf[: buf.index("(")]
        m = re.search(r"([A-Za-z_]\w*)\s*$", head)
        if not m or m.group(1) in C_KEYWORDS:
            i = j + 1
            continue
        name = m.group(1)
        prefix = head[: m.start()].strip()
        if not prefix or "=" in prefix or prefix.endswith(","):
            i = j + 1
            continue
        if re.search(r"\b(typedef|return|else|while|for|switch|if)\b", prefix):
            i = j + 1
            continue

        tail = buf[buf.rindex(")") + 1:].strip()
        is_def = tail == "" or tail.startswith("{")
        if tail == "":
            k = j + 1
            while k < len(lines) and not lines[k].strip():
                k += 1
            is_def = k < len(lines) and lines[k].lstrip().startswith("{")
        if is_def:
            sig = re.sub(r"\s+", " ", buf).rstrip("{").strip()
            if len(sig) > 118:
                sig = sig[:115] + "..."
            res.append((i + 1, name, sig))
        i = j + 1
    return res


def local_includes(text: str) -> list[str]:
    return sorted(set(re.findall(r'#\s*include\s+"([^"]+)"', text)))


def system_includes(text: str) -> list[str]:
    return sorted(set(re.findall(r"#\s*include\s+<([^>]+)>", text)))


def config_refs(text: str) -> list[str]:
    return sorted(set(re.findall(r"\bCONFIG_[A-Z0-9_]+", text)))


DEV_RE = re.compile(r"/dev/[A-Za-z0-9_%\-\.]+")
MOUNT_RE = re.compile(r'"(/(?:proc|tmp|mnt|data)[A-Za-z0-9_/\-\.]*)"')


def dev_nodes(text: str) -> list[str]:
    nodes = {n.rstrip(".") for n in DEV_RE.findall(text)}
    nodes |= set(MOUNT_RE.findall(text))
    return sorted(n for n in nodes if len(n) > 5)


def parse_kconfig(rel: str, text: str) -> list[dict]:
    entries: list[dict] = []
    cur: dict | None = None
    for raw in text.splitlines():
        m = re.match(r"^\s*(menu)?config\s+([A-Z0-9_]+)\s*$", raw)
        if m:
            cur = {
                "name": m.group(2), "file": rel, "type": "", "prompt": "",
                "default": [], "depends": [], "select": [],
            }
            entries.append(cur)
            continue
        if cur is None:
            continue
        if raw and not raw[0].isspace():
            cur = None
            continue
        m = re.match(r'^\s+(bool|int|hex|string|tristate)\s*(?:"([^"]*)")?', raw)
        if m:
            cur["type"] = m.group(1)
            if m.group(2):
                cur["prompt"] = m.group(2)
            continue
        m = re.match(r"^\s+default\s+(.+?)\s*$", raw)
        if m:
            cur["default"].append(m.group(1))
            continue
        m = re.match(r"^\s+depends on\s+(.+?)\s*$", raw)
        if m:
            cur["depends"].append(m.group(1))
            continue
        m = re.match(r"^\s+select\s+(.+?)\s*$", raw)
        if m:
            cur["select"].append(m.group(1))
    return entries


def parse_defconfig(text: str) -> dict[str, str]:
    out: dict[str, str] = {}
    for raw in text.splitlines():
        raw = raw.strip()
        m = re.match(r"^(CONFIG_[A-Z0-9_]+)=(.*)$", raw)
        if m:
            out[m.group(1)] = m.group(2)
            continue
        m = re.match(r"^# (CONFIG_[A-Z0-9_]+) is not set$", raw)
        if m:
            out[m.group(1)] = "(not set)"
    return out


def md_escape(s: str) -> str:
    return s.replace("|", "\\|")


# --------------------------------------------------------------------------
# model
# --------------------------------------------------------------------------
class Model:
    def __init__(self) -> None:
        self.rels = discover()
        self.text: dict[str, str] = {rel: read(rel) for rel in self.rels}
        self.by_basename: dict[str, list[str]] = defaultdict(list)
        for rel in self.rels:
            self.by_basename[os.path.basename(rel)].append(rel)

        self.funcs: dict[str, list[tuple[int, str, str]]] = {}
        self.incl: dict[str, list[str]] = {}
        self.sysincl: dict[str, list[str]] = {}
        self.cfgs: dict[str, list[str]] = {}
        self.devs: dict[str, list[str]] = {}
        for rel, txt in self.text.items():
            if kind_of(rel) in ("c-source", "c-header"):
                self.funcs[rel] = c_functions(txt)
                self.incl[rel] = local_includes(txt)
                self.sysincl[rel] = system_includes(txt)
                self.devs[rel] = dev_nodes(txt)
            self.cfgs[rel] = config_refs(txt)

        # resolve local includes to repo files, build reverse index
        self.dep: dict[str, list[str]] = {}
        self.rdep: dict[str, set[str]] = defaultdict(set)
        for rel, incs in self.incl.items():
            resolved: list[str] = []
            for inc in incs:
                base = os.path.basename(inc)
                cands = self.by_basename.get(base, [])
                if len(cands) > 1:
                    same = [c for c in cands
                            if os.path.dirname(c) == os.path.dirname(rel)]
                    cands = same or cands
                if cands:
                    resolved.append(cands[0])
                    self.rdep[cands[0]].add(rel)
            self.dep[rel] = sorted(set(resolved))

        # Kconfig
        self.kentries: list[dict] = []
        for rel in self.rels:
            if kind_of(rel) == "kconfig":
                self.kentries += parse_kconfig(rel, self.text[rel])
        self.kdefined = {e["name"] for e in self.kentries}
        self.kdefined_cfg = {"CONFIG_" + n for n in self.kdefined}

        self.cfg_users: dict[str, set[str]] = defaultdict(set)
        for rel, cfgs in self.cfgs.items():
            for c in cfgs:
                self.cfg_users[c].add(rel)

        self.defconfigs: dict[str, dict[str, str]] = {
            rel: parse_defconfig(self.text[rel])
            for rel in self.rels if kind_of(rel) == "defconfig"
        }

        # NSH builtin commands from app Makefiles
        self.commands: list[dict] = []
        for rel in self.rels:
            if os.path.basename(rel) != "Makefile" or not rel.startswith("app/"):
                continue
            txt = self.text[rel]
            m = re.search(r"^PROGNAME\s*[:+]?=\s*(\S+)", txt, re.M)
            if not m:
                continue
            mainsrc = re.search(r"^MAINSRC\s*[:+]?=\s*(\S+)", txt, re.M)
            module = re.search(r"^MODULE\s*[:+]?=\s*\$\((CONFIG_\w+)\)", txt, re.M)
            stack = re.search(r"^STACKSIZE\s*[:+]?=\s*(\S+)", txt, re.M)
            d = os.path.dirname(rel)
            self.commands.append({
                "cmd": m.group(1),
                "dir": d,
                "main": f"{d}/{mainsrc.group(1)}" if mainsrc else "",
                "config": module.group(1) if module else "",
                "stack": stack.group(1) if stack else "",
            })
        self.commands.sort(key=lambda c: c["cmd"])

        # backlinks from hand-written architecture pages
        self.arch_links: dict[str, set[str]] = defaultdict(set)
        self.arch_pages: list[str] = []
        if ARCH_DIR.is_dir():
            for p in sorted(ARCH_DIR.rglob("*.md")):
                vault_rel = p.relative_to(VAULT_DIR).with_suffix("").as_posix()
                self.arch_pages.append(vault_rel)
                body = p.read_text(encoding="utf-8", errors="replace")
                for target in re.findall(r"\[\[generated/files/([^\]|#]+)", body):
                    self.arch_links[target.strip()].add(vault_rel)

    # ---------------------------------------------------------------- digest
    def digest(self) -> str:
        h = hashlib.sha256()
        h.update(TOOL_VERSION.encode())
        for rel in self.rels:
            h.update(rel.encode())
            h.update(hashlib.sha256(self.text[rel].encode()).digest())
        for page in self.arch_pages:
            h.update(page.encode())
            body = (VAULT_DIR / (page + ".md")).read_bytes()
            h.update(hashlib.sha256(body).digest())
        return h.hexdigest()


# --------------------------------------------------------------------------
# rendering
# --------------------------------------------------------------------------
def render_file_page(m: Model, rel: str) -> str:
    txt = m.text[rel]
    kind = kind_of(rel)
    layer = layer_of(rel)
    nlines = txt.count("\n") + 1
    base = os.path.basename(rel)

    out: list[str] = []
    out.append("---")
    out.append("codemap: file")
    out.append(f'path: "{rel}"')
    out.append(f"layer: {layer}")
    out.append(f"kind: {kind}")
    out.append(f"lines: {nlines}")
    out.append("tags:")
    out.append("  - codemap/file")
    out.append(f"  - codemap/layer/{layer}")
    out.append(f"  - codemap/kind/{kind}")
    out.append("---")
    out.append("")
    out.append(f"# {base}")
    out.append("")
    out.append(f"`{rel}` · {nlines} 行 · **{LAYER_TITLE[layer]}** · `{kind}`")
    out.append("")
    out.append(GENERATED_BANNER)

    if kind in ("c-source", "c-header"):
        summary = leading_comment(txt)
    elif kind in ("shell", "python"):
        summary = shell_or_python_header(txt)
    else:
        summary = ""
    if summary:
        out.append("## 文件头说明（源码摘录）")
        out.append("")
        out.append("\n".join("> " + s if s else ">" for s in summary.splitlines()))
        out.append("")

    if kind == "kconfig":
        entries = [e for e in m.kentries if e["file"] == rel]
        if entries:
            out.append("## 本文件定义的 Kconfig 选项")
            out.append("")
            out.append("| 选项 | 类型 | 提示 | 默认 | depends on |")
            out.append("| --- | --- | --- | --- | --- |")
            for e in sorted(entries, key=lambda x: x["name"]):
                out.append(
                    "| `{}` | {} | {} | {} | {} |".format(
                        e["name"], e["type"] or "-",
                        md_escape(e["prompt"]) or "-",
                        md_escape(", ".join(e["default"])) or "-",
                        md_escape(", ".join(e["depends"])) or "-",
                    )
                )
            out.append("")

    if kind == "defconfig":
        cfg = m.defconfigs.get(rel, {})
        local = {k: v for k, v in cfg.items() if k in m.kdefined_cfg}
        out.append(f"## 本仓自有选项的取值（共 {len(cfg)} 项配置，其中本仓定义 {len(local)} 项）")
        out.append("")
        if local:
            out.append("| 选项 | 值 |")
            out.append("| --- | --- |")
            for k in sorted(local):
                out.append(f"| `{k}` | `{local[k]}` |")
        else:
            out.append("*本文件未启用任何本仓 Kconfig 自有选项。*")
        out.append("")
        out.append(f"完整取值见源文件；跨 defconfig 对比见 [[generated/kconfig|Kconfig 索引]]。")
        out.append("")

    funcs = m.funcs.get(rel, [])
    if funcs:
        pub = [f for f in funcs if not f[2].startswith("static")]
        prv = [f for f in funcs if f[2].startswith("static")]
        out.append(f"## 函数定义（{len(funcs)} 个）")
        out.append("")
        for title, group in (("对外可见", pub), ("文件内部 (static)", prv)):
            if not group:
                continue
            out.append(f"### {title}")
            out.append("")
            out.append("| 行 | 签名 |")
            out.append("| --- | --- |")
            for line, _name, sig in group:
                out.append(f"| {line} | `{md_escape(sig)}` |")
            out.append("")

    deps = m.dep.get(rel, [])
    if deps:
        out.append("## 依赖的本仓头文件")
        out.append("")
        for d in deps:
            out.append(f"- {link(d)} — `{d}`")
        out.append("")

    ext = [i for i in m.sysincl.get(rel, []) if i.startswith(("nuttx/", "arch/", "sys/"))]
    if ext:
        out.append("## 依赖的 openvela/NuttX 接口（上游，不在本仓）")
        out.append("")
        out.append(", ".join(f"`<{i}>`" for i in ext))
        out.append("")

    rdeps = sorted(m.rdep.get(rel, ()))
    if rdeps:
        out.append("## 被以下文件包含")
        out.append("")
        for d in rdeps:
            out.append(f"- {link(d)} — `{d}`")
        out.append("")

    own = [c for c in m.cfgs.get(rel, []) if c in m.kdefined_cfg]
    if own:
        out.append("## 引用的本仓 Kconfig 选项")
        out.append("")
        for c in own:
            out.append(f"- `{c}` → [[generated/kconfig#{c[7:]}|定义]]")
        out.append("")

    nodes = m.devs.get(rel, [])
    if nodes:
        out.append("## 涉及的设备节点 / 挂载点")
        out.append("")
        out.append(", ".join(f"`{n}`" for n in nodes))
        out.append("")
        out.append("见 [[generated/device-nodes|设备节点索引]]。")
        out.append("")

    backs = sorted(m.arch_links.get(rel, ()))
    out.append("## 相关架构页（手写）")
    out.append("")
    if backs:
        for b in backs:
            out.append(f"- [[{b}]]")
    else:
        out.append("*暂无手写页引用本文件。若它承担了某条关键流程，"
                   "请在 `codemap/architecture/` 里补一段并链接过来。*")
    out.append("")
    out.append("---")
    out.append("")
    out.append("← [[generated/index|文件索引]] · [[README|代码地图首页]]")
    out.append("")
    return "\n".join(out)


def render_index(m: Model) -> str:
    out: list[str] = []
    out.append("---\ncodemap: index\ntags:\n  - codemap/index\n---")
    out.append("")
    out.append("# 文件索引")
    out.append("")
    out.append(GENERATED_BANNER)

    total_lines = sum(m.text[r].count("\n") + 1 for r in m.rels)
    out.append(f"共 **{len(m.rels)}** 个纳入地图的文件、约 **{total_lines}** 行。")
    out.append("")
    out.append("纳入范围 = git 已跟踪 + 未被 `.gitignore` 忽略的未跟踪文件，"
               "位于 `board/` `app/` `quickapp/` `external/` 之下。"
               "被忽略的本地内容（`docs/` `notes/` `sim_tests/` `*.a` 等）不会出现在这里。")
    out.append("")

    by_layer: dict[str, list[str]] = defaultdict(list)
    for rel in m.rels:
        by_layer[layer_of(rel)].append(rel)

    out.append("## 分层概览")
    out.append("")
    out.append("| 层 | 文件数 | 行数 |")
    out.append("| --- | --- | --- |")
    for layer in ("chip", "board", "app", "board-sample", "quickapp", "cp-vendor", "other"):
        rels = by_layer.get(layer)
        if not rels:
            continue
        lines = sum(m.text[r].count("\n") + 1 for r in rels)
        out.append(f"| {LAYER_TITLE[layer]} | {len(rels)} | {lines} |")
    out.append("")

    for layer in ("chip", "board", "app", "board-sample", "quickapp", "cp-vendor", "other"):
        rels = by_layer.get(layer)
        if not rels:
            continue
        out.append f"" if False else None  # placeholder removed below
    out = [x for x in out if x is not None]

    for layer in ("chip", "board", "app", "board-sample", "quickapp", "cp-vendor", "other"):
        rels = sorted(by_layer.get(layer, []))
        if not rels:
            continue
        out.append(f"## {LAYER_TITLE[layer]}")
        out.append("")
        out.append("| 文件 | 类型 | 行 | 函数 | 一句话 |")
        out.append("| --- | --- | --- | --- | --- |")
        for rel in rels:
            txt = m.text[rel]
            first = ""
            if kind_of(rel) in ("c-source", "c-header"):
                summary = leading_comment(txt)
                if summary:
                    para = summary.split("\n\n")[0].replace("\n", " ")
                    para = re.sub(r"^" + re.escape(rel) + r"\s*", "", para).strip()
                    first = para[:110] + ("…" if len(para) > 110 else "")
            out.append("| {} | {} | {} | {} | {} |".format(
                link(rel), kind_of(rel), txt.count("\n") + 1,
                len(m.funcs.get(rel, [])) or "-", md_escape(first) or "-",
            ))
        out.append("")

    out.append("---")
    out.append("")
    out.append("← [[README|代码地图首页]] · [[generated/symbols|符号索引]] · "
               "[[generated/kconfig|Kconfig 索引]] · [[generated/device-nodes|设备节点]] · "
               "[[generated/nsh-commands|NSH 命令]]")
    out.append("")
    return "\n".join(out)


def render_symbols(m: Model) -> str:
    out: list[str] = []
    out.append("---\ncodemap: symbols\ntags:\n  - codemap/index\n---")
    out.append("")
    out.append("# 符号索引（函数定义）")
    out.append("")
    out.append(GENERATED_BANNER)

    rows: list[tuple[str, str, int, str]] = []
    for rel, funcs in m.funcs.items():
        for line, name, sig in funcs:
            rows.append((name, rel, line, sig))
    rows.sort(key=lambda r: (r[0], r[1], r[2]))
    out.append(f"共 **{len(rows)}** 个函数定义。重名说明同名 static 函数出现在多个文件。")
    out.append("")
    out.append("| 函数 | 文件 | 行 | 签名 |")
    out.append("| --- | --- | --- | --- |")
    for name, rel, line, sig in rows:
        out.append(f"| `{name}` | {link(rel)} | {line} | `{md_escape(sig)}` |")
    out.append("")
    out.append("← [[generated/index|文件索引]] · [[README|代码地图首页]]")
    out.append("")
    return "\n".join(out)


def render_kconfig(m: Model) -> str:
    out: list[str] = []
    out.append("---\ncodemap: kconfig\ntags:\n  - codemap/index\n---")
    out.append("")
    out.append("# Kconfig 索引（本仓定义的配置项）")
    out.append("")
    out.append(GENERATED_BANNER)

    dcs = sorted(m.defconfigs)
    out.append(f"本仓 Kconfig 共定义 **{len(m.kentries)}** 个选项；"
               f"随仓提供 **{len(dcs)}** 份 defconfig。")
    out.append("")
    if dcs:
        out.append("## defconfig 一览")
        out.append("")
        out.append("| defconfig | 配置项数 | 其中本仓自有 |")
        out.append("| --- | --- | --- |")
        for rel in dcs:
            cfg = m.defconfigs[rel]
            local = [k for k in cfg if k in m.kdefined_cfg]
            out.append(f"| {link(rel, rel)} | {len(cfg)} | {len(local)} |")
        out.append("")

    out.append("## 选项详情")
    out.append("")
    for e in sorted(m.kentries, key=lambda x: x["name"]):
        name = e["name"]
        out.append(f"### {name}")
        out.append("")
        out.append(f"- 定义于：{link(e['file'], e['file'])}")
        out.append(f"- 类型：`{e['type'] or '-'}`　提示：{e['prompt'] or '-'}")
        if e["default"]:
            out.append(f"- default：{', '.join('`' + d + '`' for d in e['default'])}")
        if e["depends"]:
            out.append(f"- depends on：{', '.join('`' + d + '`' for d in e['depends'])}")
        if e["select"]:
            out.append(f"- select：{', '.join('`' + d + '`' for d in e['select'])}")
        vals = []
        for rel in dcs:
            v = m.defconfigs[rel].get("CONFIG_" + name)
            if v is not None:
                vals.append(f"`{os.path.basename(os.path.dirname(rel))}`={v}")
        out.append(f"- defconfig 取值：{', '.join(vals) if vals else '未在任何 defconfig 中出现'}")
        users = sorted(m.cfg_users.get("CONFIG_" + name, ()))
        if users:
            out.append("- 被引用于：" + ", ".join(link(u) for u in users))
        out.append("")

    out.append("← [[generated/index|文件索引]] · [[README|代码地图首页]]")
    out.append("")
    return "\n".join(out)


def render_devnodes(m: Model) -> str:
    node_files: dict[str, set[str]] = defaultdict(set)
    for rel, nodes in m.devs.items():
        for n in nodes:
            node_files[n].add(rel)
    for rel, cfg in m.defconfigs.items():
        for k, v in cfg.items():
            for n in DEV_RE.findall(v):
                node_files[n.strip('"')].add(rel)

    out: list[str] = []
    out.append("---\ncodemap: device-nodes\ntags:\n  - codemap/index\n---")
    out.append("")
    out.append("# 设备节点 / 挂载点索引")
    out.append("")
    out.append(GENERATED_BANNER)
    out.append("按源码中出现的字符串字面量统计。`%d`/`%c` 之类是格式串，"
               "实际节点号由调用处决定。")
    out.append("")
    out.append("| 节点 | 出现于 |")
    out.append("| --- | --- |")
    for n in sorted(node_files):
        out.append(f"| `{n}` | " + ", ".join(link(r) for r in sorted(node_files[n])) + " |")
    out.append("")
    out.append("← [[generated/index|文件索引]] · [[README|代码地图首页]]")
    out.append("")
    return "\n".join(out)


def render_commands(m: Model) -> str:
    out: list[str] = []
    out.append("---\ncodemap: nsh-commands\ntags:\n  - codemap/index\n---")
    out.append("")
    out.append("# NSH 命令索引（本仓 app/）")
    out.append("")
    out.append(GENERATED_BANNER)
    out.append("从各应用 `Makefile` 的 `PROGNAME` / `MODULE` / `STACKSIZE` 提取。")
    out.append("")
    out.append("| 命令 | 目录 | 入口源文件 | Kconfig 开关 | 栈 |")
    out.append("| --- | --- | --- | --- | --- |")
    for c in m.commands:
        cfg = c["config"]
        enabled = []
        for rel in sorted(m.defconfigs):
            if cfg and m.defconfigs[rel].get(cfg) == "y":
                enabled.append(os.path.basename(os.path.dirname(rel)))
        cfgtxt = f"`{cfg}`" if cfg else "-"
        if enabled:
            cfgtxt += "<br>启用于：" + ", ".join(f"`{e}`" for e in enabled)
        out.append("| `{}` | `{}` | {} | {} | {} |".format(
            c["cmd"], c["dir"],
            link(c["main"]) if c["main"] in m.text else "-",
            cfgtxt, c["stack"] or "-",
        ))
    out.append("")
    out.append("← [[generated/index|文件索引]] · [[README|代码地图首页]]")
    out.append("")
    return "\n".join(out)


# --------------------------------------------------------------------------
# main
# --------------------------------------------------------------------------
def generate(m: Model) -> None:
    if FILES_DIR.exists():
        shutil.rmtree(FILES_DIR)
    GEN_DIR.mkdir(parents=True, exist_ok=True)

    for rel in m.rels:
        target = FILES_DIR / (rel + ".md")
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(render_file_page(m, rel), encoding="utf-8")

    (GEN_DIR / "index.md").write_text(render_index(m), encoding="utf-8")
