def broken_links() -> list[tuple[str, str]]:
    """[(page, target)] for every [[wikilink]] in the vault that resolves to
    no file.  Keeps the hand-written pages honest as files get renamed."""
    bad: list[tuple[str, str]] = []
    for p in sorted(VAULT_DIR.rglob("*.md")):
        page = p.relative_to(VAULT_DIR).as_posix()
        body = p.read_text(encoding="utf-8", errors="replace")
        for raw in re.findall(r"\[\[([^\]]+)\]\]", body):
            target = raw.split("|")[0].split("#")[0].strip()
            if not target:
                continue
            if (VAULT_DIR / (target + ".md")).is_file():
                continue
            if (VAULT_DIR / target).is_file():
                continue
            bad.append((page, target))
    return bad


